<?php require __DIR__.'/auth.php';guard();require dirname(__DIR__).'/config.php';$q=trim($_GET['q']??'');$tester=$_GET['tester']??'';$w=[];$p=[];if($q!==''){$w[]='(full_name LIKE ? OR email LIKE ? OR school LIKE ?)';$p=array_fill(0,3,"%$q%");}if(in_array($tester,['yes','maybe','no'])){$w[]='willing_to_test=?';$p[]=$tester;}$where=$w?' WHERE '.implode(' AND ',$w):'';$s=$pdo->prepare("SELECT COUNT(*) FROM student_survey_responses$where");$s->execute($p);$total=$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(DISTINCT school) FROM student_survey_responses$where");$s->execute($p);$schools=$s->fetchColumn();$s=$pdo->prepare("SELECT * FROM student_survey_responses$where ORDER BY created_at DESC LIMIT 100");$s->execute($p);$rows=$s->fetchAll();$feat=[];$x=$pdo->query("SELECT answer_json FROM student_survey_answers WHERE question_key='valuable_features'");foreach($x as $a)foreach(json_decode($a['answer_json'],true)?:[] as $v)$feat[$v]=($feat[$v]??0)+1;arsort($feat);?><!doctype html><html><head><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="admin.css"><title>Cavibe Dashboard</title></head><body><header><b>Cavibe Survey Admin</b><nav><a href="export.php">Export CSV</a><a href="logout.php">Sign out</a></nav></header><main><h1>Waiting List Dashboard</h1><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search name, email or school"><select name="tester"><option value="">All testers</option><option value="yes">Yes</option><option value="maybe">Maybe</option><option value="no">No</option></select><button>Filter</button></form><section class="kpis"><div><small>Total signups</small><strong><?=$total?></strong></div><div><small>Schools represented</small><strong><?=$schools?></strong></div></section><section class="panels"><div class="panel"><h2>Most-requested features</h2><?php foreach(array_slice($feat,0,10,true) as $k=>$v):?><p><span><?=e($k)?></span><b><?=$v?></b></p><?php endforeach;?></div><div class="panel"><h2>Tester interest</h2><?php foreach(['yes','maybe','no'] as $t):$c=$pdo->prepare("SELECT COUNT(*) FROM student_survey_responses WHERE willing_to_test=?");$c->execute([$t]);?><p><span><?=ucfirst($t)?></span><b><?=$c->fetchColumn()?></b></p><?php endforeach;?></div></section><div class="panel table"><h2>Responses</h2><table><tr><th>Student</th><th>School</th><th>Tester</th><th>Date</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small><?=e($r['email'])?></small></td><td><?=e($r['school'])?></td><td><?=e($r['willing_to_test'])?></td><td><?=e($r['created_at'])?></td><td><a href="response.php?id=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></table></div></main></body></html>